		}
	}
	if viper.IsSet(dbHost) {
		cfg.Database.Host = viper.GetString(dbHost)
	}
	if viper.IsSet(dbPath) {
		cfg.Database.Path = viper.GetString(dbPath)
	}
	if viper.IsSet(dbPort) {
		value := viper.GetString(dbPort)
